package com.tanidikvar.api.answer.repository;
import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AnswerLikeRepository{private final JdbcTemplate jdbc;public AnswerLikeRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public boolean visible(UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM answers a JOIN questions q ON q.id=a.question_id WHERE a.id=? AND a.deleted_at IS NULL AND a.moderated_at IS NULL AND q.deleted_at IS NULL)",Boolean.class,id));}public boolean liked(UUID id,UUID user){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM answer_likes WHERE answer_id=? AND user_id=? AND deleted_at IS NULL)",Boolean.class,id,user));}public void set(UUID id,UUID user,boolean liked){jdbc.update("INSERT INTO answer_likes(answer_id,user_id,deleted_at) VALUES (?,?,CASE WHEN ? THEN NULL ELSE clock_timestamp() END) ON CONFLICT(answer_id,user_id) DO UPDATE SET deleted_at=CASE WHEN ? THEN NULL ELSE clock_timestamp() END,version=answer_likes.version+1",id,user,liked,liked);}public long count(UUID id){return jdbc.queryForObject("SELECT count(*) FROM answer_likes WHERE answer_id=? AND deleted_at IS NULL",Long.class,id);}}
